    type: "port",
    parent: "CL-BI",
    coords: [-73.1550, -37.0305],
    name: {
      de: "Hafen Coronel",
      hu: "Coronel kikötő",
      ro: "Portul Coronel",
      en: "Port of Coronel"},
    descriptionAdvanced: {
      de: "Der Hafen von Coronel ist der größte Hafenterminal in der Region Biobío und gilt als einer der bedeutendsten Exporthäfen für Forstprodukte in ganz Chile. Er liegt etwa 30 Kilometer südlich der Großstadt Concepción und blickt auf eine lange Tradition zurück, die ursprünglich fest in der Kohleförderung des 19. Jahrhunderts verwurzelt war. Nach dem Ende der Kohleära wandelte sich der Standort zu einem hochmodernen Mehrzweckterminal, der heute primär Zellstoff, Holzprodukte und landwirtschaftliche Erzeugnisse umschlägt. Die Anlage umfasst drei große Piers und spezialisierte Lagerbereiche für Container sowie moderne Kühlhäuser für den Export von hochwertigem Obst und Fisch. Dank seiner tiefen Gewässer können im Hafen von Coronel große Schiffe der Post-Panamax-Klasse sicher anlegen, was die Effizienz im internationalen Handel steigert. Die strategische Lage am Pazifik ermöglicht einen direkten und kostengünstigen Zugang zu den Wachstumsmärkten in Asien und Nordamerika. Zudem ist der Hafen ein unverzichtbarer Arbeitgeber für die lokale Gemeinde und fördert die industrielle Diversifizierung der gesamten Region.",
      hu: "Coronel kikötője a Biobío régió legnagyobb és legmodernebb terminálja, amely Chile erdészeti termékexportjának egyik legfontosabb központja. A Concepción városától mintegy 30 kilométerre délre található kikötő gazdag múltra tekint vissza, amely eredetileg az ország szénbányászati korszakához kapcsolódott. A szénbányák bezárása után a létesítmény egy sokoldalú, magánkézben lévő terminállá alakult, amely ma főként cellulózt, faárut és mezőgazdasági termékeket kezel. A kikötő három fő mólóval, speciális konténertárolókkal és kiterjedt hűtőházi kapacitással rendelkezik a gyümölcs- és tenger gyümölcsei exportjának támogatására. Mélyvízi adottságai lehetővé teszik a legnagyobb Post-Panamax típusú teherhajók kiszolgálását is, ami versenyelőnyt jelent a globális kereskedelemben. Stratégiai elhelyezkedése a Csendes-óceán partján közvetlen kapcsolatot biztosít az ázsiai és észak-amerikai piacokhoz. A kikötő nemcsak gazdasági motor, hanem a helyi közösség legnagyobb foglalkoztatója és a regionális fejlődés záloga.",
      ro: "Portul Coronel este cel mai mare terminal maritim din regiunea Biobío și un pilon fundamental pentru exporturile forestiere ale statului Chile. Situat la aproximativ 30 de kilometri sud de Concepción, portul păstrează o moștenire istorică importantă, fiind centrul vital al epocii miniere a cărbunelui din secolul trecut. Odată cu declinul mineritului, complexul a fost reinventat într-un terminal multifuncțional de clasă mondială, gestionând astăzi volume masive de celuloză, cherestea și produse agro-industriale. Facilitățile portuare includ trei diguri principale și zone vaste de depozitare pentru containere, precum și depozite frigorifice de ultimă generație pentru exportul de fructe și fructe de mare. Datorită adâncimii naturale a apelor sale, portul are capacitatea de a găzdui nave gigantice de tip Post-Panamax, optimizând fluxurile comerciale internaționale. Poziția sa strategică pe coasta Pacificului facilitează accesul direct către piețele emergente din Asia și America de Nord. Portul rămâne motorul economic principal al comunei Coronel, susținând mii de locuri de muncă directe și indirecte.",
      en: "The Port of Coronel is the largest and most significant maritime terminal in the Biobío Region, serving as a premier hub for Chile's extensive forest product exports. Located approximately 30 kilometers south of Concepción, the port boasts a storied heritage, having originated as a central link in the nation's coal mining industry during the 19th century. Following the industry's transition, the facility evolved into a highly efficient multipurpose terminal that now specializes in wood pulp, timber, and agricultural goods. Its infrastructure is comprised of three major piers and expansive container yards, complemented by state-of-the-art cold storage units for fresh fruit and seafood exports. The port’s deep-water draft allows it to accommodate large Post-Panamax vessels, significantly enhancing its role in global logistics. Its strategic Pacific coast location provides streamlined access to major markets in Asia and North America. As a leading regional employer, the Port of Coronel is vital to the industrial growth and economic stability of the surrounding urban areas.",
    },
