      hu: ["Rang: A Biobío régió legnagyobb kikötője", "Terület: kb. 80 hektár", "Éves forgalom: több mint 7 millió tonna áru", "Infrastruktúra: 3 fő móló és modern konténerterminál", "Hajótípusok: Post-Panamax képesség", "Export: Chilei cellulóz egyik fő kilépési pontja"],
      ro: ["Statut: Cel mai mare port din regiunea Biobío", "Suprafață: aprox. 80 de hectare", "Trafic anual: peste 7 milioane de tone de marfă", "Infrastructură: 3 diguri comerciale principale", "Capacitate nave: Compatibil cu navele Post-Panamax", "Principale produse: Celuloză, lemn și fructe"],
