      ro: "Un port privat major din regiunea Biobío, care manipulează în principal produse forestiere.",
      en: "A major private port in the Biobío Region, mainly handling forest products.",
      es: "Un gran puerto privado en la región del Biobío que maneja principalmente productos forestales.",
      pt: "Um grande porto privado na região de Biobío que movimenta principalmente produtos florestais.",
      fr: "Un grand port privé dans la région de Biobío qui traite principalement des produits forestiers.",
