      es: ["Situada a gran altura en los Andes.", "Considerada un enorme yacimiento de cobre."],
      pt: ["Localizada em grande altitude nos Andes.", "Considerada uma enorme jazida de cobre."],
      fr: ["Située en haute altitude dans les Andes.", "Considérée comme un gisement de cuivre massif."],
